function prepareArticleSlot({ scheduledAt, brief, spreadsheetId, sheetName, postStatus }) {
  const date = new Date(scheduledAt);
  if (typeof scheduledAt !== "string" || !Number.isFinite(date.getTime()))
    throw Error("The trigger did not supply a schedule timestamp.");
  if (typeof brief !== "string" || !brief.trim() || brief.length > 4000)
    throw Error("Set an editorial brief up to 4,000 characters.");
  if (
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    spreadsheetId === "YOUR_SPREADSHEET_ID" ||
    typeof sheetName !== "string" ||
    !sheetName.trim() ||
    sheetName.length > 100 ||
    /[\x00-\x1f\x7f]/.test(sheetName)
  ) {
    throw Error("Set the spreadsheet ID and an existing sheet tab.");
  }
  if (!["publish", "draft"].includes(postStatus))
    throw Error("Choose publish or draft for WordPress.");
  const stamp = date.toISOString().slice(0, 16).replace(/\D/g, "");
  return {
    slug: "scheduled-article-" + stamp,
    spreadsheetId,
    sheetName,
    range: "'" + sheetName.replaceAll("'", "''") + "'!A:C",
    postStatus,
    brief: brief.trim(),
    delayMs: Math.max(1, Math.floor(Math.random() * (6 * 60 * 60 * 1000))),
  };
}
export default (input) => {
  const slot = prepareArticleSlot(input);
  return { slot, delayMs: slot.delayMs };
};

