function articleResponseRequest({ brief }) {
  const text = { type: "string" };
  const list = { type: "array", items: text };
  const section = {
    type: "object",
    additionalProperties: false,
    required: ["heading", "subheading", "paragraphs", "bullets"],
    properties: { heading: text, subheading: text, paragraphs: list, bullets: list },
  };
  return {
    model: "gpt-6-luna",
    store: false,
    max_output_tokens: 9000,
    instructions:
      "Write a complete article from the editor’s brief. Return plain text in every field. Include a short introduction, three to six factual, useful sections with one or more paragraphs, and a conclusion with practical advice. Use subheadings and bullet lists when useful. Give three to five concrete English image search keywords. Do not invent research, statistics, quotes, links or firsthand claims.",
    input: brief,
    text: {
      format: {
        type: "json_schema",
        name: "scheduled_article",
        strict: true,
        schema: {
          type: "object",
          additionalProperties: false,
          required: ["title", "introduction", "sections", "conclusion", "keywords"],
          properties: {
            title: text,
            introduction: text,
            sections: { type: "array", items: section },
            conclusion: text,
            keywords: list,
          },
        },
      },
    },
  };
}

function structuredDraftReply(reply) {
  const messages = reply?.output?.filter((x) => x?.type === "message");
  const contents = messages?.[0]?.content;
  if (
    reply?.status !== "completed" ||
    messages?.length !== 1 ||
    messages[0].role !== "assistant" ||
    messages[0].status !== "completed" ||
    contents?.length !== 1 ||
    contents[0].type !== "output_text"
  ) {
    throw Error("OpenAI did not complete the article request");
  }
  return JSON.parse(contents[0].text);
}

function escapeDraftHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function renderScheduledArticle(article, escape) {
  function text(input, max, empty = false) {
    if (
      typeof input !== "string" ||
      (!empty && !input.trim()) ||
      input.length > max ||
      /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(input)
    )
      throw Error("The model did not return a complete article.");
    return input.trim();
  }
  const title = text(article?.title, 240);
  if (/[<>\r\n]/.test(title)) throw Error("The article title must be plain text.");
  if (
    !Array.isArray(article.sections) ||
    article.sections.length < 3 ||
    article.sections.length > 6 ||
    !Array.isArray(article.keywords) ||
    article.keywords.length < 3 ||
    article.keywords.length > 5
  ) {
    throw Error("The article needs three to six sections and three to five image keywords.");
  }
  const keywords = article.keywords.map((keyword) => text(keyword, 28));
  if (keywords.some((keyword) => !/^[A-Za-z0-9][A-Za-z0-9 -]*$/.test(keyword)))
    throw Error("Image keywords must be plain English search terms.");
  const paragraph = (value) => "<p>" + escape(text(value, 3600)) + "</p>";
  const sections = article.sections
    .map((section) => {
      if (
        !Array.isArray(section.paragraphs) ||
        !section.paragraphs.length ||
        section.paragraphs.length > 5 ||
        !Array.isArray(section.bullets) ||
        section.bullets.length > 8
      )
        throw Error("The article has an incomplete section.");
      const heading = "<h2>" + escape(text(section.heading, 150)) + "</h2>";
      const subheading = text(section.subheading, 150, true);
      const bullets = section.bullets
        .map((bullet) => "<li>" + escape(text(bullet, 500)) + "</li>")
        .join("");
      return (
        heading +
        (subheading ? "<h3>" + escape(subheading) + "</h3>" : "") +
        section.paragraphs.map(paragraph).join("") +
        (bullets ? "<ul>" + bullets + "</ul>" : "")
      );
    })
    .join("\n");
  const content =
    "<h1>" +
    escape(title) +
    "</h1>" +
    paragraph(article.introduction) +
    "\n" +
    sections +
    "\n<h2>Conclusion</h2>" +
    paragraph(article.conclusion);
  if (content.length > 45000)
    throw Error("The rendered article exceeds the sheet cell size budget.");
  return { title, content, query: keywords.join(" "), logKeywords: keywords.join("+") };
}
export default async ({ slot }, context) => {
  const result = await context.actions.call("openai.create_response", articleResponseRequest(slot));
  return { article: renderScheduledArticle(structuredDraftReply(result), escapeDraftHtml) };
};

