function confirmedArticleRow(reply, slot) {
  const range =
    typeof reply?.updatedRange === "string" && reply.updatedRange.match(/^(.*)!A([1-9]\d*):C\2$/);
  const tab = range && range[1].replace(/^'(.*)'$/, "$1").replaceAll("''", "'");
  if (
    reply?.spreadsheetId !== slot.spreadsheetId ||
    reply.updatedRows !== 1 ||
    reply.updatedColumns !== 3 ||
    reply.updatedCells !== 3 ||
    tab !== slot.sheetName
  )
    throw Error(
      "Google Sheets did not confirm the expected article row. Check the log before recovery.",
    );
  return reply.updatedRange;
}
export default async ({ article, slot }, context) => {
  const reply = await context.actions.call("googlesheets.spreadsheets_values_append", {
    spreadsheetId: slot.spreadsheetId,
    range: slot.range,
    valueInputOption: "RAW",
    majorDimension: "ROWS",
    insertDataOption: "INSERT_ROWS",
    values: [[article.title, article.content, article.logKeywords]],
  });
  const sheetRange = confirmedArticleRow(reply, slot);
  await context.state.set(slot.slug, { status: "logged", sheetRange });
  return { sheetRange };
};

