function confirmedArticlePost(post, slot) {
  if (
    !Number.isSafeInteger(post?.id) ||
    post.id < 1 ||
    post.slug !== slot.slug ||
    post.status !== slot.postStatus
  ) {
    throw Error("WordPress did not confirm the expected post. Check its slug before recovery.");
  }
  return { postId: post.id, slug: post.slug, status: post.status };
}
export default async ({ post, slot, sheetRange }, context) => {
  const result = await context.actions.call("wordpress.create_post", post);
  const receipt = confirmedArticlePost(result?.post, slot);
  await context.state.set(slot.slug, { ...receipt, sheetRange });
  return { ...receipt, sheetRange };
};
